"""Exploratory C14 ablation: give the 30 original seeds equal additional weight.

The validation and historical test sets have been used in earlier experiments.
This run cannot establish independent generalization or complete the quality gate.
"""
import base64
import io
import collections
import csv
import gzip
import hashlib
import json
import random
import re
import sys
import time
import zipfile
import subprocess
from pathlib import Path

# Kaggle's image ships torchao 0.10, incompatible with its installed PEFT.
# This experiment does not use torchao quantization; remove it from this
# ephemeral notebook environment before PEFT checks optional integrations.
subprocess.run([sys.executable, '-m', 'pip', 'uninstall', '-y', 'torchao'], check=True)

SOURCE_B64 = ''
DATA_B64 = ''
DATA_HASH = '9097601e2a66f98e0463472071370980b974ce05a4f53c8312a431ad69d7edaf'
EXPECTED_TRAIN_HASH = 'ef7b24c2835b8e21dd507f022c5dc83878b6a8e2f7e66c69aa4db332bc557773'
EXPECTED_TEST_HASH = '4778906558df177f717a22214c0b91f3cbf72f76915bd59da2aa1a923d994e2d'
SOURCE_HASHES = {
    'runtime/ekido_runtime/distill.py': 'cdb17d6d3596d6b25f5f50d20344a79d378413a55ea910d22595ee7b15bae633',
    'runtime/ekido_runtime/llm.py': 'e3cb02a2cfad62dcf99484dd7759756897a1fe7239ea1e8bf880e6c63869bf6a',
    'runtime/ekido_runtime/train.py': 'abb9153518e16bf43b399c0605bfac72970de67409035199f103e8d9e44e7178',
    'packages/ekido_core/ekido_core/recipes.py': '1c1a77ac39015a0e5f7700dd65a9cc3d890c82a3feebe22e566fc4650f607e80',
    'packages/ekido_core/ekido_core/job_spec.py': 'a69557983f43a73bb15413011bc0d9b07f7c15d8e8174f3bf9fadfc0e15c6459',
}
MODEL = 'Qwen/Qwen2.5-1.5B-Instruct'
REVISION = '989aa7980e4cf806f80c7fef2b1adb7bc71aa306'


def digest(data):
    return hashlib.sha256(data).hexdigest()


def normalize(s):
    return ' '.join(s.casefold().split())


def prepare(source, payload):
    """No GPU needed: verify source and derive the predeclared training rows."""
    if digest(payload) != DATA_HASH:
        raise RuntimeError('embedded run12 dataset hash does not match')
    for rel, expected in SOURCE_HASHES.items():
        if digest((source / rel).read_bytes()) != expected:
            raise RuntimeError(f'source fingerprint mismatch: {rel}')
    train_path = source / 'data' / 'train.csv'
    if digest(train_path.read_bytes()) != EXPECTED_TRAIN_HASH:
        raise RuntimeError('seed source hash does not match')
    with train_path.open(encoding='utf-8', newline='') as f:
        original = list(csv.DictReader(f))
    labels = ('complaint', 'order', 'question', 'refund', 'other')
    rng = random.Random(42)
    seeds = [row for label in labels for row in rng.sample([r for r in original if r['label'] == label], 6)]
    records = [json.loads(line) for line in payload.decode('utf-8').splitlines() if line.strip()]
    generated = [{k: row[k] for k in ('text', 'label')} for row in records if row.get('split') == 'train']
    validation = [{k: row[k] for k in ('text', 'label')} for row in records if row.get('split') == 'test']
    if len(generated) != 446 or len(validation) != 100 or len(seeds) != 30:
        raise RuntimeError('unexpected row counts')
    if collections.Counter(row['label'] for row in seeds) != {label: 6 for label in labels}:
        raise RuntimeError('seed distribution mismatch')
    val_inputs = {normalize(row['text']) for row in validation}
    training = generated + seeds + [dict(row) for row in seeds for _ in range(5)]
    if any(normalize(row['text']) in val_inputs for row in training):
        raise RuntimeError('exact input overlap with validation')
    return generated, seeds, training, validation


def evaluate(model, tokenizer, rows, recipe, generate_answers, passes):
    labels = tuple(recipe.labels)
    prompts = [recipe.prompt(row['text']) for row in rows]
    answers = generate_answers(model, tokenizer, prompts, max_new_tokens=recipe.max_answer_tokens,
                               max_prompt_tokens=508, device='cuda')
    if len(answers) != len(rows):
        raise RuntimeError('incomplete evaluation output')
    results = []
    for row, answer in zip(rows, answers):
        predicted = next((w for w in re.findall(r'[a-z]+', answer.lower()) if w in labels), '')
        results.append({'text': row['text'], 'gold': row['label'], 'answer': answer,
                        'predicted': predicted, 'passed': bool(passes(recipe.recipe_id, answer, row['label']))})
    per_label = {}
    for label in labels:
        subset = [x for x in results if x['gold'] == label]
        per_label[label] = {'correct': sum(x['passed'] for x in subset), 'total': len(subset)}
    return {'correct': sum(x['passed'] for x in results), 'total': len(results),
            'per_label': per_label, 'examples': results}


def main():
    import torch
    import subprocess
    from safetensors.torch import load_file
    print('TORCH:', torch.__version__, 'CUDA build:', torch.version.cuda, flush=True)
    try:
        diagnostic = subprocess.run(['nvidia-smi', '--query-gpu=name,memory.total', '--format=csv,noheader'],
                                    capture_output=True, text=True, timeout=20)
        print('GPU_DIAGNOSTIC:', diagnostic.returncode, diagnostic.stdout.strip(), diagnostic.stderr.strip(), flush=True)
    except (OSError, subprocess.TimeoutExpired) as exc:
        print('GPU_DIAGNOSTIC_UNAVAILABLE:', type(exc).__name__, str(exc)[:200], flush=True)
    if not torch.cuda.is_available():
        raise RuntimeError('This experiment requires a Kaggle CUDA GPU')
    source = Path('/kaggle/working/c14-embedded-source')
    source.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(SOURCE_B64))) as archive:
        for item in archive.infolist():
            target = (source / item.filename).resolve()
            if not target.is_relative_to(source.resolve()):
                raise RuntimeError('unsafe source archive path')
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.read(item))
    for path in (source / 'runtime', source / 'packages' / 'ekido_core'):
        sys.path.insert(0, str(path))
    from ekido_core.recipes import recipe, passes
    from ekido_runtime import distill, train
    from ekido_runtime.llm import load_model, load_tokenizer, generate_answers

    payload = gzip.decompress(base64.b64decode(DATA_B64))
    generated, seeds, training, validation = prepare(source, payload)
    out = Path('/kaggle/working/c14-equal-seed-weight')
    out.mkdir(parents=True, exist_ok=True)
    print('GPU:', torch.cuda.get_device_name(0), flush=True)
    print('Rows:', len(generated), 'generated +', len(seeds), 'seeds + 150 equally repeated seed rows', flush=True)
    print('Train labels:', dict(collections.Counter(row['label'] for row in training)), flush=True)
    dataset = out / 'dataset.jsonl'
    dataset_sha, nbytes = train.write_dataset(dataset, training, validation)
    spec = distill.build_student_spec('ticket-sorter-hinglish', student_model=MODEL,
                                      student_revision=REVISION, digest=dataset_sha, nbytes=nbytes,
                                      train_rows=len(training), test_rows=len(validation), steps=400)
    spec['optimizer']['lr'] = 3e-4
    spec['checkpoint_every_steps'] = 80
    config = {'micro_batch': 2, 'accumulation': 4, 'amp': 'fp16', 'grad_checkpointing': True,
              'attention_impl': 'sdpa', 'loader_workers': 0}
    (out / 'spec.json').write_text(json.dumps(spec, indent=2) + '\n', encoding='utf-8')
    (out / 'seed_rows.json').write_text(json.dumps(seeds, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    curve, previous, base_validation = {}, None, None
    start = time.monotonic()
    for segment in range(5):
        evidence = train.run_training(spec, dataset, out / 'train', device='cuda', exec_config=config,
                                      eval_before=segment == 0, stop_after=80, resume=previous)
        step = evidence['completed_step']
        curve[str(step)] = evidence['eval']['pass_rate']
        previous = Path(evidence['checkpoints'][-1])
        if segment == 0 and evidence.get('base_eval'):
            base_validation = evidence['base_eval']['pass_rate']
        print('VALIDATION', step, curve[str(step)], flush=True)
    best_step = 400  # Preregistered fixed final step; no checkpoint selection on validation.
    best_path = out / 'train' / 'checkpoints' / f'step-{best_step}'
    print('FIXED FINAL STEP (VALIDATION REUSED):', best_step, curve[str(best_step)], flush=True)

    # This is a historical comparison, not an untouched independent test.
    test_path = source / 'data' / 'test.csv'
    if digest(test_path.read_bytes()) != EXPECTED_TEST_HASH:
        raise RuntimeError('historical test source hash mismatch')
    with test_path.open(encoding='utf-8', newline='') as f:
        historical = list(csv.DictReader(f))
    if {normalize(x['text']) for x in training} & {normalize(x['text']) for x in historical}:
        raise RuntimeError('exact input overlap with historical test')
    r = recipe('ticket-sorter-hinglish')
    tok = load_tokenizer(MODEL, REVISION)
    model = load_model(MODEL, REVISION, device='cuda', dtype=torch.float16)
    trained = train.apply_lora(model, spec)
    missing, unexpected = trained.load_state_dict(load_file(str(best_path / 'trainable.safetensors')), strict=False)
    if any('lora_' in k for k in missing) or unexpected:
        raise RuntimeError('selected checkpoint did not load cleanly')
    trained.eval()
    val_result = evaluate(trained, tok, validation, r, generate_answers, passes)
    historical_result = evaluate(trained, tok, historical, r, generate_answers, passes)
    summary = {
        'purpose': 'exploratory equal seed weighting; reused validation and historical test are not independent',
        'source_run12_dataset_sha256': DATA_HASH, 'dataset_sha256': dataset_sha,
        'seed_count': 30, 'seed_rule': '6 per label, Random(42) from original train.csv',
        'training_rows': len(training), 'training_labels': dict(collections.Counter(x['label'] for x in training)),
        'intervention': '446 previously generated verified rows plus 30 original seed rows; repeat every seed five more times',
        'extra_label_uses': '100 labelled validation rows; prior run12 also used additional labels for diagnostics',
        'base_validation': base_validation, 'validation_curve': curve, 'selected_step': best_step,
        'selection_rule': 'fixed final step 400 before evaluation',
        'validation': val_result, 'historical_test': historical_result,
        'independent_test': None, 'gpu': torch.cuda.get_device_name(0),
        'training_seconds': round(time.monotonic() - start, 1),
    }
    (out / 'summary.json').write_text(json.dumps(summary, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    with zipfile.ZipFile(out / 'selected_checkpoint.zip', 'w', compression=zipfile.ZIP_DEFLATED) as z:
        for path in sorted(best_path.iterdir()):
            if path.is_file(): z.write(path, arcname=f'step-{best_step}/{path.name}')
    print('RESULT', json.dumps({'validation': val_result['correct'] / val_result['total'],
                                'historical_test': historical_result['correct'] / historical_result['total'],
                                'independent_test': None, 'selected_step': best_step}), flush=True)


if __name__ == '__main__':
    main()
